function contains(table, i)
    for k, v in ipairs(table) do
        if v == i then
            return true, k
        end
    end
    return false
end

cruiser_top = false
for _, v in ipairs(cruiser_top_moons) do
    if type(v) == "string" then
        if moon.name == v then
            cruiser_top = true
            break
        end
    else
        if moon.id == v then
            cruiser_top = true
            break
        end
    end
end

function randomize(position)
    return randomize_scaled(position, 0.05)
end

function randomize_scaled(position, scale)
    return Vector3(position.x + (math.random() - 0.5) * scale, position.y, position.z + (math.random() - 0.5) * scale)
end

function randomize_xy_scaled(position, scale)
    return Vector3(position.x + (math.random() - 0.5) * scale, position.y + (math.random() - 0.5) * scale, position.z)
end

raycast_cache = {}
function below(position, name)
    if name == nil then
        return randomize(raycast(position))
    elseif raycast_cache[name] ~= nil then
        return randomize(raycast_cache[name])
    else
        raycast_cache[name] = raycast(position)
        return randomize(raycast_cache[name])
    end
end

function cupboard_or(cupboard_pos, fallback_pos)
    if unlockables[UNLOCKABLE_CUPBOARD] then
        return ItemPos(randomize_xy_scaled(cupboard_pos, 0.02)):with_parent(PARENT_CUPBOARD)
    elseif fallback_pos == nil then
        return nil
    else
        return ItemPos(randomize_scaled(raycast(fallback_pos), 0.02))
    end
end

function cupboard_or_rot(cupboard_pos, fallback_pos, fallback_rot)
    if unlockables[UNLOCKABLE_CUPBOARD] then
        return ItemPos(randomize_xy_scaled(cupboard_pos, 0.02)):with_parent(PARENT_CUPBOARD)
    else
        return ItemPos(randomize_scaled(raycast(fallback_pos), 0.02)):with_rotation(fallback_rot)
    end
end

function cupboard_rot_or_rot(cupboard_pos, cupboard_rot, fallback_pos, fallback_rot)
    if unlockables[UNLOCKABLE_CUPBOARD] then
        return ItemPos(randomize_xy_scaled(cupboard_pos, 0.02)):with_parent(PARENT_CUPBOARD):with_rotation(cupboard_rot)
    else
        return ItemPos(randomize_scaled(raycast(fallback_pos), 0.02)):with_rotation(fallback_rot)
    end
end

function first_x_on_cruiser(item, x, cruiser_pos, cruiser_top_pos, cruiser_rot, fallback_pos)
    if unlockables[UNLOCKABLE_CRUISER] and item.index - 1 < x then
        return ItemPos((function()
            if cruiser_top then
                return cruiser_top_pos
            else
                return cruiser_pos
            end
        end)()):with_parent(PARENT_CRUISER):with_rotation(cruiser_rot)
    else
        return fallback_pos
    end
end

item_on_cruiser = {}
function first_x_on_cruiser_where(item, x, predicate, cruiser_pos, cruiser_top_pos, cruiser_rot, fallback_pos)
    if item_on_cruiser[item.name] == nil then
        item_on_cruiser[item.name] = 0
    end
    if unlockables[UNLOCKABLE_CRUISER] and predicate(item) and item_on_cruiser[item.name] < x then
        item_on_cruiser[item.name] = item_on_cruiser[item.name] + 1
        return ItemPos((function()
            if cruiser_top then
                return cruiser_top_pos
            else
                return cruiser_pos
            end
        end)()):with_parent(PARENT_CRUISER):with_rotation(cruiser_rot)
    else
        return fallback_pos
    end
end

fallback_tool_items = {}
last_fallback_tool_items = {}
fallback_tool_items_c = 0
function fallback_tool_item(i, v)
    if fallback_tool_items[v.name] == nil then
        if fallback_tool_items_c % 2 == 0 then
            fallback_tool_items[v.name] = raycast(Vector3(0 + fallback_tool_items_c / 2, RAYCAST_SHIP_FLOOR, -6.4))
        else
            fallback_tool_items[v.name] = raycast(Vector3(0 + (fallback_tool_items_c - 1) / 2, RAYCAST_SHIP_FLOOR, -7.4))
        end
        fallback_tool_items_c = fallback_tool_items_c + 1
        last_fallback_tool_items = { v.name }
    end
    if last_fallback_tool_items[1] == v.name then
        table.insert(last_fallback_tool_items, i)
    end
    retval[i] = fallback_tool_items[v.name]
end

