if fallback_tool_items_c % 2 ~= 0 then
    pos = raycast(Vector3(0 + (fallback_tool_items_c - 1) / 2, RAYCAST_SHIP_FLOOR, -6.9))
    for _, i in ipairs(last_fallback_tool_items) do
        if _ > 1 then
            retval[i] = randomize_scaled(pos, 0.02)
        end
    end
end

if tools_only or scrap_only or cruiser_only then
    for i, v in pairs(retval) do
        if tools_only then
            if items[i].scrap and not contains(TOOLS, items[i].name) then
                retval[i] = nil
            end
        elseif scrap_only then
            if not items[i].scrap or contains(TOOLS, items[i].name) then
                retval[i] = nil
            end
        elseif cruiser_only then
            if v.parent ~= PARENT_CRUISER then
                retval[i] = nil
            end
        end
    end
end

return retval
